#!/usr/local/bin/prhm-node
'use strict';
const fs=require('node:fs');
const path=require('node:path');
const os=require('node:os');
const crypto=require('node:crypto');
const cp=require('node:child_process');
const http=require('node:http');
const vm=require('node:vm');

const UPGRADE_VERSION='1.14.1-honartik-iticket-v14-preflight-upgrade-v1';
const ADAPTER_VERSION='1.14.1-honartik-iticket-v14-preflight-readonly';
const TOOL='honartik_iticket_v14_preflight_readonly';
const PATHS=Object.freeze({agentServer:'/home/agent/ssh-agent-api/server.js',agentRoute:'/home/agent/ssh-agent-api/honartikIticketV14PreflightRoutes.js',mcpRegistry:'/home/agent/ssh-mcp-server/src/core/registry.js',mcpPlugin:'/home/agent/ssh-mcp-server/src/plugins/honartikIticketPreflight.js',hostActionsV2:'/home/agent/ssh-mcp-server/src/plugins/hostActionsV2.js',payload:'/opt/prhm-agent-readonly-actions/honartik-iticket-v14-preflight.js',marker:'/var/lib/prhm-host-actions/honartik-iticket-v14-preflight-readonly-v1.json'});
const SOURCES=Object.freeze({agentRoute:path.join(__dirname,'honartik-iticket-v14-preflight-readonly-routes.js'),payload:path.join(__dirname,'bootstrap-host-actions-v14-honartik-iticket-dark-backend-batch1.js')});
const SERVICES=Object.freeze(['prhm-agent-api.service']);
const OLD=Object.freeze({agentServer:'7171a63ac5a7e72cd7c0af7d0c90e7d16abd17ed1af623441c44387444e77b23',registry:'faec4810f1a8059f7c9bf7cb02a277d3e515b8f15bbc52dde8ddce347aa7155f',agentRoute:'a2c69c0066c514b938eb304bb38325199f81a269320829d0508d9b80323e4c92',mcpPlugin:'963529d9ebec49e64ea98798ca0dbf2cd8542f4fb648213a05cb3351f83d28a2',payload:'1cd8e33bdecaa2ebffc086c778e7938cb33b57b31e6abab21a183972259a0059'});
const NEW=Object.freeze({agentServer:OLD.agentServer,registry:OLD.registry,agentRoute:'a2c3480018f7e8cfb69eeda9cb92e122735f0694ecae3d7e69bd37b8124b5189',mcpPlugin:OLD.mcpPlugin,payload:'a1d5e590f5798226fb8bf39652b15e2e341ece82c23c2591ba839fad12834b20'});
const BOUND_KEYS=Object.freeze(Object.keys(OLD));
function sha(b){return crypto.createHash('sha256').update(b).digest('hex');}
function fail(c){throw new Error(c);}
function readBytes(f){return fs.readFileSync(f);}
function readText(f){return fs.readFileSync(f,'utf8');}
function hashes(){return {agentServer:sha(readBytes(PATHS.agentServer)),registry:sha(readBytes(PATHS.mcpRegistry)),agentRoute:sha(readBytes(PATHS.agentRoute)),mcpPlugin:sha(readBytes(PATHS.mcpPlugin)),payload:sha(readBytes(PATHS.payload)),hostActionsV2:sha(readBytes(PATHS.hostActionsV2))};}
function markerOk(m,a){if(!m||m.schema_version!=='prhm.readonly-adapter-install.v1'||m.version!==ADAPTER_VERSION||m.tool!==TOOL)fail('installed_marker_invalid');for(const k of BOUND_KEYS)if(m.installed_sha256?.[k]!==a[k])fail('installed_marker_sha_mismatch:'+k);}
function same(a,b){return Object.keys(b).every(k=>a[k]===b[k]);}
function classifyHashes(a,m){markerOk(m,a);if(same(a,OLD))return 'upgrade_required';if(same(a,NEW))return 'already_upgraded';fail('installed_state_drift');}
function checkSource(label,file,expected){const b=readBytes(file);if(sha(b)!==expected)fail('source_sha_mismatch:'+label);let s=b.toString('utf8');if(s.startsWith('#!'))s=s.slice(s.indexOf('\n')+1);try{new vm.Script(s,{filename:file});}catch{fail('source_syntax_invalid:'+label);}return b;}
function prepare(){if(os.hostname()!=='prhm-production.prhm.ir')fail('wrong_host:'+os.hostname());for(const f of Object.values(PATHS))if(!fs.existsSync(f))fail('installed_path_missing:'+f);const m=JSON.parse(readText(PATHS.marker));const a=hashes();const state=classifyHashes(a,m);return {state,marker:m,actual:a,route:checkSource('agentRoute',SOURCES.agentRoute,NEW.agentRoute),payload:checkSource('payload',SOURCES.payload,NEW.payload)};}
function preflight(){const p=prepare();return {ok:true,schema_version:'prhm.readonly-adapter-upgrade-preflight.v1',upgrade_version:UPGRADE_VERSION,adapter_version:ADAPTER_VERSION,tool:TOOL,preflight_only:true,state:p.state,baseline_match:true,control_plane_mutation:false,production_mutation:false,production_application_tree_mutation:false,database_mutation:false,deploy:false,external_network:false,token_read:false};}
function atomicWrite(file,bytes,st){const tmp=file+'.upgrade-'+process.pid+'-'+Date.now()+'.tmp';const fd=fs.openSync(tmp,'wx',st.mode&0o777);try{fs.writeFileSync(fd,bytes);fs.fsyncSync(fd);}finally{fs.closeSync(fd);}fs.chmodSync(tmp,st.mode&0o777);fs.chownSync(tmp,st.uid,st.gid);fs.renameSync(tmp,file);}
function backupFile(file,dir,label){const st=fs.statSync(file),target=path.join(dir,label+'.bak');fs.copyFileSync(file,target,fs.constants.COPYFILE_EXCL);fs.chmodSync(target,0o600);return {file,target,st};}
function restoreBackup(b){atomicWrite(b.file,readBytes(b.target),b.st);}
function systemctl(...args){return cp.execFileSync('/usr/bin/systemctl',args,{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:90000}).trim();}
function httpHealth(){return new Promise(resolve=>{const q=http.request({host:'127.0.0.1',port:8099,path:'/health',method:'GET'},r=>{let n=0,x=[];r.on('data',c=>{n+=c.length;if(n<=65536)x.push(c);});r.on('end',()=>{if(r.statusCode!==200||n>65536)return resolve(false);try{resolve(JSON.parse(Buffer.concat(x).toString()).ok===true);}catch{resolve(false);}});});q.setTimeout(2000,()=>{q.destroy();resolve(false);});q.on('error',()=>resolve(false));q.end();});}
async function health(){if(systemctl('is-active','prhm-agent-api.service')!=='active')fail('service_not_active:prhm-agent-api.service');for(let i=0;i<30;i++){if(await httpHealth())return;await new Promise(r=>setTimeout(r,500));}fail('health_timeout:agent-api');}
function buildUpgradedMarker(m,h,dir,now){return {...m,installed_sha256:{...h},last_upgrade:{version:UPGRADE_VERSION,upgraded_at:now,backup_dir:dir,from:{agentRoute:OLD.agentRoute,payload:OLD.payload},to:{agentRoute:NEW.agentRoute,payload:NEW.payload}}};}
async function upgrade(){const p=prepare();if(p.state==='already_upgraded')return {ok:true,schema_version:'prhm.readonly-adapter-upgrade-result.v1',upgrade_version:UPGRADE_VERSION,already_upgraded:true,control_plane_mutation:false,production_mutation:false,database_mutation:false,deploy:false,external_network:false,token_read:false,rollback:{performed:false}};const dir='/var/backups/prhm-host-actions-v14-1-iticket-preflight-upgrade-'+new Date().toISOString().replace(/[-:.TZ]/g,'').slice(0,14)+'-'+crypto.randomBytes(4).toString('hex');fs.mkdirSync(dir,{recursive:false,mode:0o700});const backups={agentRoute:backupFile(PATHS.agentRoute,dir,'agentRoute'),payload:backupFile(PATHS.payload,dir,'payload'),marker:backupFile(PATHS.marker,dir,'marker')};let mutated=false;try{mutated=true;atomicWrite(PATHS.agentRoute,p.route,fs.statSync(PATHS.agentRoute));atomicWrite(PATHS.payload,p.payload,fs.statSync(PATHS.payload));systemctl('restart','prhm-agent-api.service');await health();const h=hashes();if(!same(h,NEW))fail('post_upgrade_state_drift');if(h.hostActionsV2!==p.actual.hostActionsV2)fail('host_actions_v2_changed_during_upgrade');const m=buildUpgradedMarker(p.marker,h,dir,new Date().toISOString());atomicWrite(PATHS.marker,Buffer.from(JSON.stringify(m,null,2)+'\n'),fs.statSync(PATHS.marker));classifyHashes(h,JSON.parse(readText(PATHS.marker)));return {ok:true,schema_version:'prhm.readonly-adapter-upgrade-result.v1',upgrade_version:UPGRADE_VERSION,already_upgraded:false,backup_dir:dir,installed_sha256:h,control_plane_mutation:true,production_mutation:false,production_application_tree_mutation:false,database_mutation:false,deploy:false,external_network:false,token_read:false,rollback:{performed:false}};}catch(e){if(mutated){try{restoreBackup(backups.marker);}catch{}try{restoreBackup(backups.payload);}catch{}try{restoreBackup(backups.agentRoute);}catch{}try{systemctl('restart','prhm-agent-api.service');}catch{}}throw e;} }
if(require.main===module){(async()=>{try{const o=process.argv.includes('--preflight-only')?preflight():await upgrade();process.stdout.write(JSON.stringify(o)+'\n');}catch(e){process.stderr.write(String(e?.stack||e)+'\n');process.exitCode=1;}})();}
module.exports={UPGRADE_VERSION,ADAPTER_VERSION,TOOL,PATHS,SOURCES,SERVICES,OLD,NEW,BOUND_KEYS,sha,classifyHashes,buildUpgradedMarker,preflight,upgrade};
